**The fix:** in `apps/shop/app/api/orders/route.ts`, the handler trusts a client-supplied `userId` query parameter (and returns *all* orders if it's omitted) instead of checking who's actually logged in — that's the IDOR letting any customer read anyone else's orders. The fix derives the user ID from the authenticated session token instead:

```ts
import { NextResponse } from 'next/server';
import { getToken } from 'next-auth/jwt';
import { db } from '../../../lib/db';

export async function GET(req: Request) {
  const token = await getToken({ req: req as any, secret: process.env.NEXTAUTH_SECRET });
  if (!token?.sub) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }
  const orders = await db.order.findMany({ where: { userId: token.sub } });
  return NextResponse.json(orders);
}
```

